for (size_t i = start; i < end; ++i) {
    Particle& p = particles[i];
    float density = selfDens;
    glm::vec3 force(0.0f);

    glm::ivec3 currentCell = getCell(&p, h);
    for (int dz = -1; dz <= 1; ++dz) {
        for (int dy = -1; dy <= 1; ++dy) {
            for (int dx = -1; dx <= 1; ++dx) {
                glm::ivec3 neighborCell = currentCell + glm::ivec3(dx, dy, dz);
                uint32_t hash = getHash(neighborCell);
                uint32_t startIdx = particleTable[hash * 2];
                uint32_t endIdx = particleTable[hash * 2 + 1];

                for (uint32_t j = startIdx; j < endIdx; ++j) {
                    Particle& neighbor = particles[j];
                    glm::vec3 r = p.position - neighbor.position;
                    float distSq = glm::length2(r);
                    if (distSq < h2 && distSq > 1e-8f) {
                        float dist = std::sqrt(distSq);
                        float w = poly6 * std::pow(h2 - distSq, 3);
                        density += mass * w;

                        float gradW = spikyGrad * std::pow(h - dist, 2);
                        glm::vec3 grad = r * (gradW / dist);
                        force -= mass * (p.pressure + neighbor.pressure) * 0.5f * grad;
                    }
                }
            }
        }
    }

    p.density = density;
    p.pressure = gasConstant * (density - restDensity);
    p.force = force;
}

